css:
/* ── Mockups. Drawn in CSS rather than shipped as screenshots, so they stay sharp at any size,
      load with the page, and can be corrected when the product moves. ────────────────────────── */
.mock{background:var(--surface);border:1px solid var(--hair);border-radius:16px;padding:16px;margin:22px 0}
.mock .cap{font-size:.76rem;color:var(--ink3);margin:12px 2px 0;text-align:center}
.mocklabel{font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3);font-weight:700;margin:0 0 12px}
.pane{background:var(--bg);border:1px solid var(--hair);border-radius:12px;padding:12px}
.pane .ph{font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3);font-weight:700;margin:0 0 10px}
.pane .ph.was{color:var(--bad)}
.pane .ph.now{color:var(--good)}
/* lift rows */
.lrow{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--hair);
  border-radius:10px;padding:9px 11px;margin-bottom:8px;position:relative;overflow:hidden}
.lrow .rail{position:absolute;left:0;top:0;bottom:0;width:4px}
.lrow .nm{font-size:.86rem;color:var(--ink);font-weight:600;line-height:1.3}
.lrow .sub{font-size:.7rem;color:var(--ink3);display:block;font-weight:400}
.lrow .wait{margin-left:auto;text-align:right;font-weight:800;font-size:.86rem;white-space:nowrap}
.lrow .rng{display:block;font-size:.68rem;color:var(--ink3);font-weight:500}
.lrow.dim{opacity:.5}
.chip{display:inline-block;font-size:.62rem;font-weight:800;padding:2px 7px;border-radius:5px;color:#04121f}
/* map */
.map{height:150px;border-radius:10px;background:linear-gradient(170deg,#12303a,#0b1a22);position:relative;overflow:hidden}
.map svg{position:absolute;inset:0;width:100%;height:100%}
.dot{position:absolute;width:11px;height:11px;border-radius:50%;border:2px solid var(--bg)}
/* season */
.scard{background:linear-gradient(165deg,rgba(254,184,77,.10),var(--surface));border:1px solid rgba(254,184,77,.3);
  border-radius:12px;padding:14px}
.big{font-family:var(--display);font-weight:850;letter-spacing:-.03em;line-height:1;font-variant-numeric:tabular-nums}
.mrow{display:flex;align-items:center;gap:9px;margin-top:8px;font-size:.8rem}
.mrow .nm{color:var(--ink);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mrow .v{color:var(--ink);font-weight:700;font-variant-numeric:tabular-nums}
.mrow .d{color:var(--ink3);font-size:.7rem;width:46px;text-align:right}
.bars .nm{font-size:.75rem;color:var(--ink2);width:92px;flex:none}
.note{font-size:.78rem;color:var(--ink3);border-left:2px solid var(--hair);padding-left:12px;margin:18px 0}
/* ── Auto-playing before/after. A GIF's job, done in CSS: nothing to download, sharp at any size,
      and it keeps working when the product moves. Both states are always in the DOM, so the
      comparison is still readable with animation switched off. ──────────────────────────────── */
.flip{position:relative}
.flip .layer{transition:opacity .5s ease}
.flip .after{position:absolute;inset:0}
.flip .tag{position:absolute;top:10px;right:10px;font-size:.62rem;font-weight:800;letter-spacing:.1em;
  text-transform:uppercase;padding:3px 8px;border-radius:6px;z-index:3}
.flip .tag.was{background:var(--bad);color:#1a0606}
.flip .tag.now{background:var(--good);color:#04121f}
@media (prefers-reduced-motion:no-preference){
  .flip .before,.flip .tag.was{animation:showFirst 7s infinite}
  .flip .after,.flip .tag.now{animation:showSecond 7s infinite}
  @keyframes showFirst{0%,42%{opacity:1}50%,92%{opacity:0}100%{opacity:1}}
.draw{stroke-dasharray:220;stroke-dashoffset:220;animation:draw 7s infinite}
@media (prefers-reduced-motion:reduce){
  .flip .after{position:static;margin-top:12px}
  .flip .tag{position:static;display:inline-block;margin-bottom:8px}
}
